	columns.LcCopy(ln, lt)
	initial.InDetect(wd, gl, fnt, et, np, loc, lt, ls, lo, tm, ii)
	heading.HdAnalyze(wd, lt, et, gl, sf, sc, hc, ws, htmp, hpr, hptxt)
