	ttRule(pa, 7000, 7500, 50000, 7550)
	ttAt(wd, ln, et, port.TextBlob("ACTIVITY"), 7600, 8000, 1, 0)
	ttAt(wd, ln, et, port.TextBlob("PostDate"), 7600, 10000, 1, 0)
