	ttAt(wd, ln, et, port.TextBlob("Fees"), 24500, 54800, 0, 0)
	ttAt(wd, ln, et, port.TextBlob("100.02"), 45000, 54800, 0, 1)
	ttAt(wd, ln, et, port.TextBlob("Interest"), 24500, 56300, 0, 0)
